insert into public.approved_interview_follow_ups(problem_id,content_version,prompt)
select p.id,1,authored.prompt from (values
('concatenation-of-array','Generalize to k copies. Explain output size, overflow checks, and how a lazy iterator could avoid allocating the full result.'),
('longest-common-prefix','Words now arrive as a stream. Maintain the common prefix after each arrival without retaining all previous words.'),
('remove-element','Require the surviving values to retain their original relative order. Implement a stable in-place version and explain its write count.'),
('majority-element','The existence guarantee is removed. Return an explicit no-majority result when appropriate, keeping constant auxiliary space.'),
('design-hashset','Replace bounded integer keys with arbitrary strings. Design collision handling and resizing, and distinguish expected from worst-case operation cost.'),
('design-hashmap','Add resizing to a bucket-based implementation. Explain rehashing, load factor, and why changing capacity changes bucket placement.'),
('sort-an-array','Require stable ordering of records by a selected numeric field. Adapt the algorithm and explain its auxiliary memory requirement.'),
('sort-colors','Allow k distinct colors numbered 0 through k-1. Compare counting with in-place partitioning as k grows.'),
('range-sum-query-2d-immutable','Allow point updates between queries. Choose a data structure and explain its update, query, and memory costs.'),
('best-time-to-buy-and-sell-stock-ii','Charge a fixed fee on each sale. Adapt the state transitions and explain why taking every positive adjacent difference no longer works.'),
('majority-element-ii','Generalize the threshold to strictly more than floor(n/k) occurrences. Explain candidate storage and final verification.'),
('subarray-sum-equals-k','Return the longest subarray summing to k instead of the count. Explain which prefix occurrence must be retained.'),
('first-missing-positive','The input is now read-only. Compare time and memory tradeoffs for finding the same answer without changing it.'),
('reverse-string','Input is now a UTF-8 string, and visible grapheme clusters must remain intact. Explain why reversing bytes or code points can be incorrect.'),
('valid-palindrome-ii','Permit up to k deletions. Define a dynamic-programming state and explain how the complexity depends on string length and k.'),
('merge-strings-alternately','Merge k character streams round-robin, skipping exhausted streams. Explain how to maintain the active streams efficiently.'),
('merge-sorted-array','Merge k sorted iterators into a single output stream. Explain the memory bound and how a heap selects each next value.'),
('remove-duplicates-from-sorted-array','Allow each distinct value to appear at most twice in the compacted prefix. Keep constant auxiliary space.'),
('4sum','Return the number of index quadruplets instead of unique value quadruplets. Explain how duplicate multiplicities change the solution.'),
('rotate-array','Process many rotations before any read of an element. Represent the accumulated rotation lazily and explain index translation.'),
('boats-to-save-people','Allow three passengers per boat. Show why the two-person greedy proof no longer directly applies and propose an exact small-input approach.'),
('contains-duplicate-ii','Handle an unbounded stream while retaining only the last k positions. Explain duplicate removal when an old value also has a newer occurrence.'),
('minimum-size-subarray-sum','Allow negative values in nums. Explain why the positive-only window fails and derive a prefix-sum monotonic-deque approach.'),
('find-k-closest-elements','The input is unsorted and read-only. Compare a size-k heap with sorting a copy, including the cost of sorted output.'),
('baseball-game','Add an undo operation that reverses the most recent score operation, including cancellations. Specify and implement the necessary history.'),
('implement-stack-using-queues','Make pop and top constant-time by moving work to push. Explain the resulting operation costs and queue ordering invariant.'),
('implement-queue-using-stacks','Explain a sequence where one pop takes linear time, and prove constant amortized cost using a potential or accounting argument.'),
('asteroid-collision','Return original indices of survivors as well as their sizes. Preserve the collision rules while maintaining provenance.'),
('online-stock-span','Limit the span to the latest W days. Explain how to expire old history without losing the nearest greater-price boundary.'),
('simplify-path','Support relative paths whose leading parent references must be preserved. Define the difference from absolute-root handling.'),
('decode-string','Return the decoded length without materializing the text. Detect when it exceeds a supplied limit, including very large repeat counts.'),
('maximum-frequency-stack','Add peek without removal. Explain why it can use the current highest-frequency group''s latest entry without changing state.'),
('search-insert-position','Allow duplicates and return both the first and last target index, or [-1,-1] when absent, in logarithmic time.'),
('guess-number-higher-or-lower','The upper bound is unknown. Use exponential probing before binary search and explain the oracle-call bound in terms of the hidden number.'),
('sqrtx','Generalize to floor of the integer kth root for k>=2. Explain an overflow-safe comparison without floating-point rounding.'),
('capacity-to-ship-packages-within-d-days','Return the daily package boundaries for an optimal capacity. Explain whether empty trailing days are needed under a within-days contract.'),
('search-in-rotated-sorted-array-ii','Give an adversarial duplicate-heavy family requiring linear comparisons. Explain why no choice of midpoint restores a guaranteed logarithmic bound.'),
('split-array-largest-sum','Also return exactly k segment boundaries achieving the optimum. Handle zero values and ensure no segment is empty.'),
('find-in-mountain-array','Explain and verify the worst-case get-call bound for length 10,000, including peak search and both sides. Show how caching affects repeated reads.'),
('reverse-linked-list-ii','Reverse every complete block of k nodes, leaving a final short block unchanged. Keep constant auxiliary space and explain boundary reconnection.'),
('design-circular-queue','Extend the structure to a fixed-capacity deque with insertion and deletion at both ends. State all full and empty invariants.'),
('lfu-cache','Add an explicit delete(key) operation while preserving constant expected time. Explain how the minimum frequency can be maintained when an entire bucket disappears.'),
('binary-tree-inorder-traversal','Describe Morris traversal with constant auxiliary space, including how every temporary threaded pointer is restored.'),
('binary-tree-preorder-traversal','Serialize tree shape as well as values using explicit null markers. Explain why preorder values alone cannot reconstruct a general binary tree.'),
('binary-tree-postorder-traversal','Compute subtree sizes in the same postorder pass. Explain the iterative stack state needed to combine child results.'),
('insert-into-a-binary-search-tree','Repeated sorted insertions produce a skewed tree. Compare an AVL or red-black tree with the current implementation''s worst-case behavior.'),
('delete-node-in-a-bst','Nodes now contain parent pointers. Explain every parent-pointer update required for zero-, one-, and two-child deletions, including the root.'),
('construct-quad-tree','Compute the logical OR of two same-size binary grids using only their quadtrees. Short-circuit uniform regions and compress the result.'),
('house-robber-iii','Return one optimal set of node references in addition to the sum. Explain reconstruction from take/skip states and tie handling.'),
('delete-leaves-with-a-given-value','Return the round in which each removed node disappears under simultaneous leaf deletion. Explain a postorder recurrence for removal rounds.'),
('single-threaded-cpu','Also return each task''s start and completion times. Include idle gaps and explain why arrivals during a running task do not interrupt it.'),
('reorganize-string','Require equal characters to be at least k positions apart. Explain a heap plus cooldown queue and how to detect impossibility.'),
('longest-happy-string','Allow at most r consecutive equal characters over an arbitrary alphabet. Define a generalized strategy and justify its maximal length.'),
('car-pooling','Return the minimum vehicle capacity required and the first location attaining that peak. Respect dropoffs and pickups at the same location.'),
('ipo','Return the chosen project indices and final capital. Explain how to retain original identifiers through sorting and heap operations.'),
('sum-of-all-subset-xor-totals','Derive a formula based on which bits occur anywhere in the input, avoiding explicit subset enumeration. Justify the count for each bit.'),
('combinations','Return combinations through a lazy iterator. Explain how to retain only the current search state and how output complexity remains unavoidable.'),
('permutations-ii','Generate the distinct permutations in lexicographic order. Explain a next-permutation approach and duplicate handling.'),
('matchsticks-to-square','Return the four groups of original stick indices when possible. Explain how symmetry pruning interacts with reconstructing a witness.'),
('partition-to-k-equal-sum-subsets','Allow zero-valued elements. Preserve the requirement of nonempty groups and explain the special case of total sum zero.'),
('n-queens-ii','Some squares are blocked. Adapt the search and explain whether the usual symmetry reductions remain valid.'),
('word-break-ii','Return only the number of valid sentences. Explain how this changes memory usage and how to handle counts exceeding machine integers.'),
('extra-characters-in-a-string','Return one optimal segmentation, marking unmatched characters explicitly. Explain predecessor storage and tie handling.'),
('island-perimeter','Allow multiple islands and enclosed lakes. Return the total land boundary including lake shores, then explain how to count only the boundary touching exterior water.'),
('verifying-an-alien-dictionary','The alphabet order is no longer supplied. Infer one order consistent with the words or report that no order exists.'),
('find-the-town-judge','Trust pairs arrive incrementally and may repeat. Maintain the degrees without double-counting repeated pairs, and explain the extra storage required.'),
('open-the-lock','Return an actual shortest sequence of lock states. Compare ordinary and bidirectional BFS reconstruction.'),
('course-schedule-iv','Support adding prerequisite edges between queries. Explain how to update reachability and how to detect a newly introduced cycle.'),
('accounts-merge','Also report the original account indices belonging to each merged group. Explain why a shared name must never merge accounts by itself.'),
('evaluate-division','An added equation may contradict existing ratios. Detect inconsistency within a stated numeric tolerance and explain a weighted-union-find approach.'),
('minimum-height-trees','Give edges positive weights. Explain why removing unweighted leaves is insufficient and propose a method to find the best vertex roots.'),
('path-with-minimum-effort','Also return a path attaining the minimum effort. Explain predecessor reconstruction and how to avoid confusing minimax cost with total cost.'),
('find-critical-and-pseudo-critical-edges-in-minimum-spanning-tree','Optimize beyond rerunning a full MST for every edge. Explain equal-weight batches, component contraction, and bridge detection.'),
('build-a-matrix-with-conditions','When impossible, return a directed cycle from one conflicting axis. Explain how the diagnostic is reconstructed.'),
('greatest-common-divisor-traversal','Return the connected components rather than a boolean. Preserve duplicate values as separate indices and handle every occurrence of 1.'),
('n-th-tribonacci-number','Compute Tn modulo a supplied positive modulus for very large n. Derive a matrix-exponentiation formulation.'),
('combination-sum-iv','Require exactly L terms in each sequence. Add the length dimension and explain why zero or negative values require a finite-length bound.'),
('perfect-squares','Return one minimum-length list of square summands. Explain how to reconstruct it from DP or BFS state.'),
('integer-break','Require exactly k positive summands. Define a correct DP state and explain how the new requirement changes the optimum.'),
('stone-game-iii','Also return Alice''s first move under optimal play. Explain how score-difference choices can reconstruct a full optimal game.'),
('unique-paths-ii','Allow removing at most one obstacle along the path. Add a resource dimension and define how a blocked start is handled.'),
('minimum-path-sum','Also count the number of minimum-cost paths. Explain combining equal-cost predecessors and handling a large count modulo a chosen modulus.'),
('last-stone-weight-ii','Return a partition of original stone indices achieving the minimum difference. Explain reconstructing subset-sum choices without reusing a stone.'),
('stone-game','Remove both the even-length and odd-total guarantees. Return Alice, Bob, or Tie using a general interval score-difference DP.'),
('stone-game-ii','Return an optimal first choice of X as well as Alice''s total. Explain how the memoized state supports reconstruction of later moves.'),
('lemonade-change','The price and accepted denominations are configurable. Give a case where the original greedy change rule fails and propose a correct small-input search.'),
('maximum-sum-circular-subarray','Return start index and length of one maximizing nonempty circular segment. Handle ties and the all-negative case.'),
('longest-turbulent-subarray','Return the earliest starting interval among maximum-length turbulent intervals. Preserve linear time and define the tie rule explicitly.'),
('jump-game-vii','Return an actual valid sequence of jump indices when reachable. Explain how to store predecessors without losing linear-time exploration.'),
('dota2-senate','Return the elimination order produced by the earliest-opponent strategy. Explain how repeated rounds map back to original senator indices.'),
('candy','Arrange children in a circle so the first and last are neighbors. Adapt the algorithm and justify the resulting minimum.'),
('meeting-rooms-iii','Return the assigned room and actual start/end for each original meeting. Explain preserving original indices and handling simultaneous releases.'),
('excel-sheet-column-title','Implement the inverse conversion and describe an overflow check for arbitrarily long titles.'),
('greatest-common-divisor-of-strings','Generalize to a list of strings. Explain iterative reduction and how an empty common divisor terminates the computation.'),
('insert-greatest-common-divisors-in-linked-list','Return a new expanded list while preserving the entire input list. Explain ownership and allocation costs.'),
('transpose-matrix','For a square matrix, transpose in place using constant auxiliary space. Explain why the same simple swaps do not directly handle a rectangular representation.'),
('roman-to-integer','Remove the validity guarantee. Reject noncanonical forms such as IIV or VX, and explain a validation strategy using canonical re-encoding.'),
('add-binary','Generalize addition to bases 2 through 36 while keeping input numbers as strings. Define digit validation and carry handling.'),
('bitwise-and-of-numbers-range','Find the bitwise OR over the same range. Derive the result from the endpoints'' shared binary prefix.'),
('minimum-array-end','Return the element at zero-based position j in the lexicographically smallest valid increasing sequence. Explain the bit-position mapping with wide arithmetic.')
) as authored(slug,prompt)
join public.problems p on p.source='leetcode' and p.slug=authored.slug;

-- Switch the actual start gate as well as the UI selection source. Keep all
-- authentication, ready-content, difficulty and single-active-session checks.
do $$
declare definition text;
begin
  definition := pg_get_functiondef('public.start_mock_interview_v2(uuid,integer,text,uuid,text[],uuid,integer,jsonb,text,text,text)'::regprocedure);
  if strpos(definition, 'collection.slug = ''neetcode-150''') = 0
    or strpos(definition, '''candidateProblemCount'')::integer not between 1 and 150') = 0 then
    raise exception 'Unexpected interview start function; inspect before upgrading';
  end if;
  definition := replace(definition, 'collection.slug = ''neetcode-150''', 'collection.slug = ''neetcode-250''');
  definition := replace(definition, '''candidateProblemCount'')::integer not between 1 and 150', '''candidateProblemCount'')::integer not between 1 and 250');
  execute definition;
end;
$$;

do $$
declare problem_count integer; topic_count integer; followup_count integer;
begin
  select count(*),count(distinct m.primary_topic_id),count(f.problem_id)
  into problem_count,topic_count,followup_count
  from public.problem_collection_memberships m
  join public.problem_collections c on c.id=m.collection_id
  join public.problems p on p.id=m.problem_id and p.active and p.interview_ready
  left join public.approved_interview_follow_ups f on f.problem_id=p.id
    and f.content_version=p.interview_content_version and f.active
  where c.slug='neetcode-250' and c.version=1;
  if problem_count<>250 or topic_count<>18 or followup_count<>250 then
    raise exception 'Incomplete NeetCode 250 inventory: % problems, % topics, % follow-ups',problem_count,topic_count,followup_count;
  end if;
  if (select count(*) from public.problem_collection_memberships m join public.problem_collections c on c.id=m.collection_id where c.slug='neetcode-150' and c.version=1)<>150 then
    raise exception 'Historical NeetCode 150 membership changed';
  end if;
end;
$$;
